sys_ux_client_script.script:
/**
 * Calls API to toggle the `complex` field for the specific integration in the sam.integration property.
 *
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
async function handler({ api, event, helpers, imports }) {
  try {
    // Get the integration title from the event context
    const item = event.context.item.value;

    console.log("Incoming event payload:", item);

    if (!item || !item.title) {
      console.error('not working properly')
        }

    const integrationTitle = item.title;
    console.log("Processing request for integration:", integrationTitle);

    // Define API URL
    const apiUrl = "/api/985627/sys_property_api/update-complex";

    // API Request Payload
    const requestData = {
      data: {
        title: integrationTitle
      }
    };

    console.log("Request Data:", JSON.stringify(requestData, null, 2));

    // Perform API Call
    const response = await helpers.snHttp(apiUrl, {
      method: 'PUT',
      body: requestData,
      headers: {
        "Content-Type": "application/json",
        "Accept": "application/json"
      }
    });

    console.log("API response:", response);

    if (response && response.response) {
      const responseData = response.response; // Already parsed JSON
      // api.addInfoMessage(`Integration "${responseData.title}" updated successfully. Complex value: ${responseData.complex}`);


      api.emit("NOW_UXF_PAGE#ADD_NOTIFICATIONS", {
                items: [
                    {
                        id: "alert2",
                        status: "positive",
                        icon: "info-circle-outline",
                        content: await helpers.translate("Integration moved to next phase"),
                        action: { type: "dismiss" },
                    },
                ],
            });
      // Refresh the component if needed
      // api.dispatch("REFRESH_DATA");
    } else {
      const errorMessage = (response && response.error) ? response.error : 'Failed to update integration';
      api.addErrorMessage(`Error: ${errorMessage}`);
    }
  } catch (error) {
    console.error("API Request Failed:", error);
    api.addErrorMessage(`API Request Failed: ${error.message}`);
  }
}
